// ============================================================
// MODULE 1: Single-Agent vs Multi-Agent Overview
// ============================================================

const overview = {
  title: "Single-Agent vs Multi-Agent Systems",

  singleAgent: {
    definition: "A single agent handles ALL tasks sequentially, one at a time.",
    characteristics: [
      "One LLM or process does everything",
      "Simple to build and debug",
      "Limited by context window size",
      "Slower for complex, multi-step tasks",
      "No parallelism — bottleneck on large jobs"
    ],
    example: "One AI reads a research paper, summarizes it, verifies facts, AND writes a report — all sequentially."
  },

  multiAgent: {
    definition: "Multiple specialized agents collaborate, each handling a specific sub-task.",
    characteristics: [
      "Agents work in parallel or in coordinated sequence",
      "Each agent has a focused role and toolset",
      "Supervisor delegates and aggregates results",
      "Scalable for complex, long-horizon tasks",
      "Resilient — one agent failing doesn't break everything"
    ],
    example: "A Supervisor delegates: Agent A researches, Agent B summarizes, Agent C verifies — then Supervisor combines outputs."
  },

  whyAgentsCollaborate: [
    "Division of expertise: each agent specializes (e.g., web search vs. code execution)",
    "Parallelism: tasks run simultaneously, cutting total time",
    "Context management: avoids overloading a single agent's context window",
    "Reliability: failures are isolated — the system can retry only the failed agent",
    "Modularity: easy to add, replace, or upgrade individual agents"
  ]
};

console.log("✅ Module 1 loaded: Overview of Single vs Multi-Agent");
return [{ json: { module: 1, data: overview } }];

// ============================================================
// MODULE 2: Core Roles, Goals & Supervisor-Worker Pattern
// ============================================================

const rolesAndPattern = {
  title: "Core Roles, Goals & Supervisor-Worker Pattern",

  coreRoles: {
    supervisor: {
      name: "Supervisor Agent",
