      responsibilities: [
        "Receives the high-level task from the user",
        "Breaks the task into smaller, assignable sub-tasks",
        "Routes sub-tasks to the correct worker agents",
        "Monitors worker progress and handles failures",
        "Aggregates and synthesizes all worker outputs",
        "Returns final consolidated result to the user"
      ],
      tools: ["task_planner", "message_router", "result_aggregator", "quality_checker"],
      goal: "Orchestrate the workflow and ensure the final output is complete and coherent"
    },

    workerAgents: [
      {
        name: "Research Agent",
        emoji: "🔍",
        role: "Gathers raw information from external sources",
        tools: ["web_search", "arxiv_lookup", "wikipedia_fetch", "url_scraper"],
        goal: "Return relevant, factual raw data on the assigned topic",
        input: "Topic/query string",
        output: "List of relevant facts, links, and raw content"
      },
      {
        name: "Summarization Agent",
        emoji: "📝",
        role: "Condenses long-form content into concise summaries",
        tools: ["llm_summarizer", "text_chunker", "key_point_extractor"],
        goal: "Produce a clear, accurate summary of the research agent's output",
        input: "Raw research content",
        output: "Structured summary with key points and insights"
      },
      {
        name: "Verification Agent",
        emoji: "✅",
        role: "Fact-checks claims against trusted sources",
        tools: ["fact_check_api", "cross_reference_search", "confidence_scorer"],
        goal: "Flag inaccuracies and assign confidence scores to each claim",
        input: "Summary with claims",
        output: "Verified summary with confidence scores and corrections"
      }
    ]
  },

  supervisorWorkerPattern: {
    description: "The Supervisor-Worker pattern is the most common multi-agent architecture.",
    flow: [
      "1. User sends a complex task to the Supervisor",
      "2. Supervisor decomposes the task into N sub-tasks",
      "3. Supervisor assigns each sub-task to a specialized Worker",
      "4. Workers execute their tasks (possibly in parallel)",
      "5. Workers return results to the Supervisor",
      "6. Supervisor validates, aggregates, and synthesizes results",
      "7. Supervisor returns the final answer to the User"
    ],
    keyPrinciples: [
      "Single point of coordination: only the Supervisor talks to the User",
      "Workers are stateless: they don't know about each other",
      "Supervisor maintains the shared state and context",
      "Delegation is explicit: Supervisor sends structured task messages"
    ]
  }
};

console.log("✅ Module 2 loaded: Roles, Goals & Supervisor-Worker Pattern");
return [{ json: { module: 2, data: rolesAndPattern } }];

