      { step: 2, action: "ANALYZE", description: "Supervisor identifies what sub-tasks are needed" },
      { step: 3, action: "PLAN", description: "Supervisor creates an execution plan (sequential or parallel)" },
      { step: 4, action: "DELEGATE", description: "Supervisor sends structured task messages to workers" },
      { step: 5, action: "MONITOR", description: "Supervisor tracks which tasks are complete/pending/failed" },
      { step: 6, action: "COLLECT", description: "Supervisor gathers all worker results" },
      { step: 7, action: "SYNTHESIZE", description: "Supervisor combines results into a coherent response" },
      { step: 8, action: "RETURN", description: "Supervisor sends final result to user" }
    ]
  }
};

console.log("✅ Module 3 loaded: Messaging Flow & Delegation");
return [{ json: { module: 3, data: messagingAndDelegation } }];

